const { owner_id = '', data_inicio = '' } = query;
const supabaseUrl = ($env && $env.SUPABASE_URL) ? $env.SUPABASE_URL : 'https://SEU_PROJETO.supabase.co';
const serviceKey  = ($env && $env.SUPABASE_SERVICE_KEY) ? $env.SUPABASE_SERVICE_KEY : 'SUA_SERVICE_KEY';

const inicio = data_inicio || (() => {
  const d = new Date();
  d.setDate(d.getDate() - 30);
  return d.toISOString().split('T')[0];
})();

try {
  const result = await this.helpers.httpRequest({
    method: 'GET',
    url: supabaseUrl + '/rest/v1/stock_movements',
    headers: { apikey: serviceKey, Authorization: 'Bearer ' + serviceKey },
    qs: {
      owner_id: 'eq.' + owner_id,
      type: 'in.(saida,consumo,desperdicio,perda,ajuste_negativo)',
      created_at: 'gte.' + inicio,
      select: 'item_name,quantity,unit,type,unit_cost,total_cost,reason,created_at',
      order: 'created_at.desc',
      limit: '5000'
    }
  });
  return JSON.stringify(result);
} catch (e) {
  return JSON.stringify({ error: e.message, tool: 'movimentacoes_saida' });
}

