const item = items[0];
const raw = item.json.output || item.json.text || item.json;
let data;
try {
  const clean = (typeof raw === 'string') ? raw.replace(/```json\n?/gi, '').replace(/```/g, '').trim() : JSON.stringify(raw);
  data = JSON.parse(clean);
} catch (e) {
  data = { raw_output: raw };
}
return [{ json: { success: true, agente: 'CMV', setor: item.json.setor, owner_id: item.json.owner_id, timestamp: new Date().toISOString(), data } }];
